drop policy if exists "Authenticated users can manage inventory items" on public.dv_accounting_inventory_items;
drop policy if exists "Authenticated users can manage inventory movements" on public.dv_accounting_inventory_movements;
drop policy if exists "Inventory managers can insert items" on public.dv_accounting_inventory_items;
create policy "Inventory managers can insert items" on public.dv_accounting_inventory_items for insert to authenticated with check (upper(coalesce((select p.role from public.dv_accounting_user_profiles p where p.user_id=auth.uid() limit 1),auth.jwt()->'app_metadata'->>'role',auth.jwt()->'user_metadata'->>'role','STAFF'))='SUPERADMIN'
 or exists(select 1 from public.dv_accounting_user_permission_overrides u where u.user_id=auth.uid() and u.permission_code='inventory.manage' and u.allowed=true)
 or exists(select 1 from public.dv_accounting_user_profiles p join public.dv_accounting_role_permission_rules r on upper(r.role)=upper(p.role) where p.user_id=auth.uid() and r.permission_code='inventory.manage' and r.allowed=true));
